const { S3Client, PutObjectCommand } = require("@aws-sdk/client-s3");
const { getSignedUrl } = require("@aws-sdk/s3-request-presigner");

// Initialize S3 Client (Region matches your infrastructure)
const s3Client = new S3Client({ region: process.env.AWS_REGION || "eu-north-1" });
const BUCKET_NAME = process.env.BUCKET_NAME || "local-cloud-queue-856805821816-eu-north-1-an"; // Replace with your actual S3 bucket name

// Standard CORS headers required for every response
const corsHeaders = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "Content-Type,Authorization",
    "Access-Control-Allow-Methods": "OPTIONS,POST,GET"
};

exports.handler = async (event) => {
    // 1. Handle browser preflight OPTIONS request safely if passed through
    const method = event.requestContext?.http?.method || event.httpMethod;
    if (method === 'OPTIONS') {
        return {
            statusCode: 200,
            headers: corsHeaders,
            body: ""
        };
    }

    try {
        // 2. Parse incoming request body from React frontend
        const body = event.body ? JSON.parse(event.body) : {};
        const fileName = body.fileName || "uploaded-file";
        const fileType = body.fileType || "application/octet-stream";

        const key = `uploads/${Date.now()}-${fileName}`;

        // 3. Create S3 PutObject command
        const command = new PutObjectCommand({
            Bucket: BUCKET_NAME,
            Key: key,
            ContentType: fileType,
        });

        // 4. Generate secure presigned URL (valid for 5 minutes / 300 seconds)
        const uploadUrl = await getSignedUrl(s3Client, command, { expiresIn: 300 });

        // 5. Return success response with CORS headers
        return {
            statusCode: 200,
            headers: corsHeaders,
            body: JSON.stringify({
                uploadUrl: uploadUrl,
                fileKey: key
            }),
        };

    } catch (error) {
        console.error("Lambda Execution Error:", error);

        // 6. Return error response WITH CORS headers so the browser sees the actual error instead of a CORS block
        return {
            statusCode: 500,
            headers: corsHeaders,
            body: JSON.stringify({ error: error.message }),
        };
    }
};
